INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (1, 'ছাত্রলীগ–পুলিশের সঙ্গে আন্দোলনকারীদের সংঘর্ষে নিহত ৬', 'https://www.prothomalo.com/bangladesh/1gwvyiambx', 'সরকারি চাকরিতে কোটাব্যবস্থা সংস্কারের দাবিতে আন্দোলন ঘিরে ঢাকা, চট্টগ্রাম ও রংপুরে সংঘর্ষে ছয়জন নিহত হয়েছেন। এর মধ্যে ঢাকায় দুজন, চট্টগ্রামে তিনজন ও রংপুরে একজন রয়েছেন। আজ মঙ্গলবার দুপুরের পর ঢাকার বেশ কয়েকটি এলাকাসহ দেশের বিভিন্ন স্থানে সংঘর্ষে আরও কয়েক শ মানুষ আহত হয়েছেন। কোটা সংস্কার আন্দোলনে যুক্ত শিক্ষার্থীদের সঙ্গে পুলিশ, ছাত্রলীগ, যুবলীগ ও ক্ষমতাসীন দলের সমর্থকদের মধ্যে এসব সংঘর্ষের ঘটনা ঘটেছে। এখনো অনেক জায়গায় সংঘর্ষ চলছে।

Six people were killed in clashes in Dhaka, Chittagong and Rangpur over the agitation demanding reform of quota system in government jobs. Among them, there are two in Dhaka, three in Chittagong and one in Rangpur. Several hundreds of people were injured in clashes in different parts of the country including several areas of Dhaka after noon on Tuesday. These clashes took place between the police, Chhatra League, Jubo League and supporters of the ruling party with the students involved in the quota reform movement. Clashes are still going on in many places.', 'https://web.archive.org/web/20240716182336/https://www.prothomalo.com/bangladesh/1gwvyiambx', 'https://i.ibb.co/SB3wsCw/8e5d59a0-856b-4d38-9f33-c4305639891d.jpg', 1, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (2, 'চট্টগ্রামে কোটা আন্দোলনকে ঘিরে সংঘর্ষ, নিহত ৩', 'https://youtu.be/yvJXWpd8ZhQ', '', 'https://youtu.be/yvJXWpd8ZhQ', 'https://img.youtube.com/vi/yvJXWpd8ZhQ/maxresdefault.jpg', 1, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (3, 'ঢাকায় সংঘর্ষের ঘটনায় আরেকজনের মৃত্যু', 'https://www.prothomalo.com/bangladesh/capital/ojbn0t8n32', 'ঢাকার সায়েন্স ল্যাব এলাকায় দুপুর থেকে ছাত্রলীগ ও যুবলীগের নেতা-কর্মীদের সঙ্গে আন্দোলনকারী শিক্ষার্থীদের সংঘর্ষ চলছে। এর মধ্যে সেখানে দুজনের মৃত্যু হয়েছে আজ মঙ্গলবার বিকেলে', 'https://web.archive.org/web/20240716183038/https://www.prothomalo.com/bangladesh/capital/ojbn0t8n32', 'https://i.ibb.co/6wDF4g7/Dhaka-College-01.jpg', 1, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (4, 'চট্টগ্রামে ওয়ার্ড কাউন্সিলরের নেতৃত্বে আন্দোলনকারীদের মারধর', 'https://www.prothomalo.com/bangladesh/district/y01l1hxa3f', 'চট্টগ্রাম নগরের প্রবর্তক মোড়ে এক ওয়ার্ড কাউন্সিলরের নেতৃত্বে কোটা সংস্কার আন্দোলনকারীদের ওপর হামলার অভিযোগ উঠেছে। আজ মঙ্গলবার বিকেল সাড়ে চারটায় চট্টগ্রাম সিটি করপোরেশনের চকবাজার ওয়ার্ডের কাউন্সিলর নূর মোস্তফার নেতৃত্বে এ হামলা হয়।', 'https://web.archive.org/web/20240716183354/https://www.prothomalo.com/bangladesh/district/y01l1hxa3f', 'https://i.ibb.co/jgxqJCw/Untitled-3.jpg', 0, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (5, 'সিলেটে দেশীয় অস্ত্র নিয়ে সড়কে অবস্থান করে ছাত্রলীগের বিক্ষোভ', 'https://www.prothomalo.com/bangladesh/district/958xluqswo', 'সিলেটে দেশীয় অস্ত্র নিয়ে সড়কে অবস্থান করে বিক্ষোভ করছেন ছাত্রলীগের নেতা-কর্মীরা। এতে অংশ নিয়েছেন সিলেট জেলা ও মহানগর ছাত্রলীগের নেতারা। এ ছাড়া সিলেটের জেলা ও মহানগর যুবলীগ, স্বেচ্ছাসেবক লীগসহ দলীয় অঙ্গসংগঠনের নেতা-কর্মীরাও বিক্ষোভে অংশ নিয়েছেন।


Chhatra League leaders and workers are protesting on the road with domestic weapons in Sylhet. Leaders of Sylhet District and Metropolitan Chhatra League participated in it. Apart from this, the leaders and workers of Sylhet''s district and metropolitan Jubo League, Swachhasebak League and other party organizations also participated in the protest.', 'https://web.archive.org/web/20240716183720/https://www.prothomalo.com/bangladesh/district/958xluqswo', 'https://images.prothomalo.com/prothomalo-bangla%2F2024-07%2F1e6d0e1a-39a6-46d4-a3fa-2f09e5b3f7dd%2FSylhet_DH0486_20240716_Sylhet_Lig_photo_24.JPG?rect=0%2C0%2C1920%2C1280&auto=format%2Ccompress&fmt=we', 0, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (6, 'রংপুরে পুলিশের সঙ্গে বিক্ষোভকারীদের সংঘর্ষে এক শিক্ষার্থী নিহত হয়েছেন', 'https://www.thedailystar.net/news/bangladesh/news/student-rangpur-killed-during-clash-between-police-and-protesters-3658216', 'A student of Rangpur''s Begum Rokeya University was killed during a clash between police and protesters seeking quota reform on the campus.', 'https://web.archive.org/web/20240716185320/https://www.thedailystar.net/news/bangladesh/news/student-rangpur-killed-during-clash-between-police-and-protesters-3658216', 'https://i3.ytimg.com/vi/jO6iEc-b1mo/hqdefault.jpg', 1, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (7, 'শাহবাগে এক দফা দাবিতে বিক্ষোভ করছে হাজার হাজার আন্দোলনকারী', 'https://www.thedailystar.net/news/bangladesh/news/thousands-protesters-demonstrate-shahbagh-one-point-demand-3669301', 'Thousands of protesters have gathered at the Shahbagh intersection in the capital this morning and blocked it to press home their one-point demand -- resignation of the government.', 'https://web.archive.org/save/https://www.thedailystar.net/news/bangladesh/news/thousands-protesters-demonstrate-shahbagh-one-point-demand-3669301', 'https://tds-images.thedailystar.net/sites/default/files/styles/big_202/public/images/2024/08/04/shahbagh_2.jpg', 0, 1, '2024-08-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (8, 'Euphoria in Bangladesh after PM Sheikh Hasina flees country', 'https://www.bbc.com/news/articles/clywww69p2vo', 'Bangladeshi Prime Minister Sheikh Hasina has resigned after weeks of deadly anti-government protests, putting an end to her more than two decades dominating the country''s politics.
Ms Hasina, 76, fled the country, reportedly landing in India on Monday.', 'https://web.archive.org/save/https://www.bbc.com/news/articles/clywww69p2vo', 'https://i.ibb.co/pLfHvGX/Euphoria-in-Bangladesh-after-PM-Sheikh-Hasina-flees-country.jpg', 0, 1, '2024-08-06');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (9, 'Hasina falls, flees', 'https://www.thedailystar.net/news/bangladesh/news/hasina-falls-flees-3670201', 'Bangladesh''s iron lady of 15 years bowed out to a people''s uprising yesterday. Serving as the prime minister since 2009, Sheikh Hasina was forced to resign and flee the country as hundreds of thousands marched towards Dhaka defying a curfew amid a continual morning drizzle.', 'https://web.archive.org/save/https://www.thedailystar.net/news/bangladesh/news/hasina-falls-flees-3670201', 'https://www.thedailystar.net/sites/default/files/styles/big_202/public/images/2024/08/05/national-parlement.jpg', 0, 1, '2024-08-06');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (10, 'দৌড়ে পালালেন জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের ভিসি', 'https://tinyurl.com/35exxps4', 'পুলিশের রাবার বুলেটে জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ে শতাধিক শিক্ষার্থী আহত হয়েছেন। এর মধ্যে, পুলিশের সহায়তায় প্রশাসনিক ভবন থেকে অবরুদ্ধ উপাচার্য অধ্যাপক মো. নূরুল আলমকে দৌড়ে পালাতে দেখা গেছে।', 'https://web.archive.org/save/https://tinyurl.com/35exxps4', 'https://i.ibb.co/LpfN4v5/147846-142.jpg', 0, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (11, 'সোহরাওয়ার্দী কলেজ ছাত্রলীগের বিরুদ্ধে যত অভিযোগ', 'https://tinyurl.com/3vwt4rhc', 'তাদের বিরুদ্ধে পাওয়া অভিযোগগুলোর মধ্যে রয়েছে মেয়াদ শেষ হলেও ছাত্রত্ব রাখা, পূর্ণাঙ্গ কমিটি না দেওয়া, চাঁদাবাজি, নারী কেলেঙ্কারি, ইভটিজিং, সাংবাদিক নির্যাতন, পরীক্ষা চলাকালীন টাকার বিনিময়ে বাথরুমে বসে প্রশ্নের সমাধান বিক্রি করাসহ একাধিক অভিযোগ।', 'https://web.archive.org/save/https://tinyurl.com/3vwt4rhc', 'https://i.ibb.co/5Kz8Hwk/149654-187.jpg', 0, 1, '2024-08-10');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (12, 'ছাত্রলীগের হামলায় দুই শতাধিক আহত', 'https://thedailycampus.com/student-movement-politics/147558/%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97%E0%A7%87%E0%A6%B0-%E0%A6%B9%E0%A6%BE%E0%A6%AE%E0%A6%B2%E0%A6%BE%E0%', 'ঢাকা বিশ্ববিদ্যালয়ে দিনভর ছাত্রলীগের হামলায় দুই শতাধিক আহত হয়েছেন বলে জানিয়েছেন কোটা সংষ্কার আন্দোলনের সমন্বয়ক নাহিদুল ইসলাম। 

আজ সোমবার রাত ৯.৩০ ঢাকা বিশ্ববিদ্যালয়ের কার্জন হলে এক সংবাদ সম্মেলনে তিনি এ কথা বলেন। 

সংবাদ সম্মেলনে সমন্বয়ক নাহিদ ইসলাম বলেন, এ হামলা পরিকল্পিতভাবে হয়েছে। সরকার এ আন্দোলন সহিংসভাবে বন্ধের চেষ্টা করছে। প্রধানমন্ত্রীর বক্তব্য প্রত্যাহারের দাবি জানিয়ে তিনি জানান, আগামীকাল বিকেল ৩.০০ টায় দেশের সব ক্যাম্পাসে বিক্ষোভ মিছিল করা হবে আন্দোলনরত শিক্ষার্থীদের পক্ষ থেকে। এরপর চলমান অবরোধ কর্মসূচিও পালন করা হবে।', 'https://web.archive.org/save/https://tinyurl.com/4wnk4f5s', 'https://i.ibb.co/MVsCWbg/147558-150.jpg', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (13, 'কোটা আন্দোলনে ছদ্মবেশে জামায়াত-শিবিরের সন্ত্রাসীরা অনুপ্রবেশ করে: প্রধানমন্ত্রী', 'https://www.prothomalo.com/bangladesh/a8rhzar0x7', 'প্রধানমন্ত্রী শেখ হাসিনা বলেছেন, জামায়াত-শিবিরের সন্ত্রাসীরা প্রাথমিকভাবে লো প্রোফাইল বজায় রেখে কোটা সংস্কার আন্দোলনে অংশগ্রহণকারীদের ছদ্মবেশে প্রবেশ করেছিল। কিন্তু পরে তারা বিপজ্জনকভাবে আন্দোলনের সামনের সারিতে চলে আসে।', 'https://web.archive.org/save/https://www.prothomalo.com/bangladesh/a8rhzar0x7', 'https://i.ibb.co/LNvyPL6/prothomalo-bangla-2024-07-8fc3755e-9565-4431-bacf-87cd00492ec2-PM-says-today.jpg', 0, 1, '2024-07-28');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (14, 'কোটা বাতিলের দাবিতে জাহাঙ্গীরনগরে বিক্ষোভ, ঢাকা-আরিচা মহাসড়ক অবরোধ', 'https://www.prothomalo.com/bangladesh/district/sp2jbrxncq', 'সরকারি চাকরিতে কোটাপদ্ধতি বাতিল ও মেধাভিত্তিক নিয়োগের পরিপত্র বহাল রাখাসহ চার দাবিতে ২০ মিনিট ঢাকা-আরিচা মহাসড়ক অবরোধ করেছেন জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের একদল শিক্ষার্থী।', 'https://web.archive.org/web/20240703021155/https://www.prothomalo.com/bangladesh/district/sp2jbrxncq', 'https://i.ibb.co/Bj5hk4G/prothomalo-bangla-2024-07-bcd00b63-1914-45fd-9653-6eb3b859f374-JU-DH1642-20240702-IMG-20240702-16191.jpg', 0, 1, '2024-07-02');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (15, 'কোটা বাতিল: দাবি আদায় না হওয়া পর্যন্ত রাজপথ ছাড়ব না', 'https://www.prothomalo.com/video/bangladesh/n4vf4ugcdm', 'বিপুলসংখ্যক শিক্ষার্থী নেমেছেন রাজপথে। সরকারি চাকরিতে কোটাব্যবস্থা বাতিল করে ২০১৮ সালে সরকারের জারি করা পরিপত্র পুনর্বহালের দাবিতে এ মিছিল।', 'https://youtu.be/Zhi_MjdIklQ', 'https://img.youtube.com/vi/Zhi_MjdIklQ/maxresdefault.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (16, 'কোটা বাতিলের দাবিতে মহাসড়ক অবরোধ বরিশাল বিশ্ববিদ্যালয়ের শিক্ষার্থীদের', 'https://www.prothomalo.com/bangladesh/district/g4tlencsm8', 'সরকারি চাকরিতে কোটা বাতিল করে মেধাভিত্তিক নিয়োগের দাবিতে তৃতীয় দিনের মতো বিক্ষোভ করেছেন বরিশাল বিশ্ববিদ্যালয়ের শিক্ষার্থীরা। আজ বুধবার বেলা সোয়া ১১টার দিকে বিশ্ববিদ্যালয়ের সামনের বরিশাল-কুয়াকাটা মহাসড়ক ধরে অবরোধ শুরু করেন তাঁরা। এদিকে এই কর্মসূচির কারণে অসংখ্য যাত্রীবাহী ও পণ্যবাহী যানবাহনে আটকে চরম ভোগান্তিতে পড়েন যাত্রী ও সংশ্লিষ্টরা। ঘোষিত চার দফা দাবি বাস্তবায়িত না হলে লাগাতার আন্দোলনের হুঁশিয়ারি দিয়েছেন আন্দোলনকারীরা।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/district/g4tlencsm8', 'https://i.ibb.co/mFFVmqt/prothomalo-bangla-2024-07-b8e3627c-e60c-4998-888b-98dd0f53ebb4-Barishal-DH0590-20240703-barishal-04.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (17, 'কোটা বাতিলের দাবিতে আজও বিক্ষোভে শিক্ষার্থীরা', 'https://www.prothomalo.com/bangladesh/c8y6j3vmok', 'সরকারি চাকরিতে কোটা বাতিল করে ২০১৮ সালে সরকারের জারি করা পরিপত্র পুনর্বহালের দাবিতে ঢাকা বিশ্ববিদ্যালয় ক্যাম্পাস থেকে বিক্ষোভ শুরু করেছেন শিক্ষার্থীরা। আজ বুধবার বেলা আড়াইটার দিকে বিশ্ববিদ্যালয়ের কেন্দ্রীয় গ্রন্থাগারের সামনে থেকে এ কর্মসূচি শুরু করেন তাঁরা।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/c8y6j3vmok', 'https://i.ibb.co/mXPvgzM/prothomalo-bangla-2024-07-846fc036-2ced-4933-8531-2c3469af33e0-9f6a1e64-dddf-4f98-8f7a-8c5ab497007d.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (18, 'কোটা বাতিলের দাবিতে দ্বিতীয় দিনের মতো শাহবাগ মোড় অবরোধ, যান চলাচল বন্ধ', 'https://www.prothomalo.com/bangladesh/xm2jadsjt6', 'সরকারি চাকরিতে কোটাব্যবস্থা বাতিল করে ২০১৮ সালে সরকারের জারি করা পরিপত্র পুনর্বহালের দাবিতে আজ বুধবার দ্বিতীয় দিনের মতো রাজধানীর শাহবাগ মোড় অবরোধ করেছেন বিপুলসংখ্যক শিক্ষার্থী ও চাকরিপ্রত্যাশী৷', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/xm2jadsjt6', 'https://i.ibb.co/NpdbCrd/prothomalo-bangla-2024-07-9024c91d-b66f-4e3f-8e06-c26265778f5b-144835a5-14c1-4b53-8df8-4cb80545bb0b.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (19, 'কোটা পুনর্বহালের প্রতিবাদে চট্টগ্রাম বিশ্ববিদ্যালয় শিক্ষার্থীদের সড়ক অবরোধ', 'https://www.prothomalo.com/bangladesh/9vyqqzxc1a', 'সরকারি চাকরিতে কোটাব্যবস্থা পুনর্বহালের প্রতিবাদে এবার চট্টগ্রাম-খাগড়াছড়ি মহাসড়ক অবরোধ করেছেন চট্টগ্রাম বিশ্ববিদ্যালয়ের শিক্ষার্থীরা। আজ বুধবার বেলা পৌনে একটায় বিশ্ববিদ্যালয়ের ১ নম্বর গেট এলাকায় অবরোধ শুরু হয়। চলে বেলা দেড়টা পর্যন্ত। এ সময় এ সড়কে দীর্ঘ যানজট দেখা দেয়।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/9vyqqzxc1a', 'https://i.ibb.co/FKkKbd5/prothomalo-bangla-2024-07-ec88c660-dae3-43ef-9c67-1122d93be084-Whats-App-Image-2024-07-03-at-16-33-2.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (20, 'কোটা বাতিলের দাবিতে আবারও জাহাঙ্গীরনগরে বিক্ষোভ, ঢাকা-আরিচা মহাসড়ক অবরোধ', 'https://www.prothomalo.com/bangladesh/district/od5uvsc5ed', 'সরকারি চাকরিতে কোটাপদ্ধতি বাতিল ও মেধাভিত্তিক নিয়োগের পরিপত্র বহাল রাখাসহ চার দাবিতে ঢাকা-আরিচা মহাসড়ক অবরোধ করে বিক্ষোভ করেছেন জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের শিক্ষার্থীরা।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/district/od5uvsc5ed', 'https://i.ibb.co/4fG7J9f/prothomalo-bangla-2024-07-c47e8826-6471-4180-8532-000b52de3f91-JU-DH1642-20240703-IMG-20240703-15313.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (21, 'মুক্তিযোদ্ধা কোটা চিরস্থায়ী করলে স্বাধীনতার মূল উদ্দেশ্যকে ধ্বংস করা হয় : জি এম কাদের', 'https://www.prothomalo.com/politics/3v1m5qjgw8', 'বীর মুক্তিযোদ্ধা সবাই অনগ্রসর নন, তাই সরকারি চাকরিতে মুক্তিযোদ্ধা কোটা রাখা সংবিধানসম্মত নয় বলে মনে করেন বিরোধীদলীয় নেতা জি এম কাদের। এই কোটার বিরোধিতা করে তিনি বলেন, মুক্তিযুদ্ধের চেতনার নামে বড় আকারে মুক্তিযোদ্ধা কোটা চিরস্থায়ী করলে স্বাধীনতার মূল উদ্দেশ্যকে ধ্বংস করা হয়।', 'https://web.archive.org/web/0/https://www.prothomalo.com/politics/3v1m5qjgw8', 'https://i.ibb.co/hYsCnbD/prothomalo-bangla-2023-06-13ea5acd-abf9-42ba-82a8-71aecdcc3e35-efcb61ad-7ab9-4784-b6ce-1aa4233c22e4.jpg', 0, 1, '2024-07-03');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (22, 'সরকারি চাকরিতে কোটা বাতিলের আন্দোলন ছড়িয়ে পড়ছে', 'https://www.prothomalo.com/bangladesh/xy5ooexy1c', 'সরকারি চাকরিতে কোটাব্যবস্থা বাতিল করে ২০১৮ সালে সরকারের জারি করা পরিপত্র পুনর্বহালের দাবিতে শিক্ষার্থী ও চাকরিপ্রত্যাশীদের আন্দোলন ছড়িয়ে পড়ছে। গতকাল বুধবার আন্দোলনকারীরা ঢাকার শাহবাগ মোড় দেড় ঘণ্টার মতো অবরোধ করে রাখেন।', 'https://web.archive.org/web/20240705012654/https://www.prothomalo.com/bangladesh/xy5ooexy1c', 'https://i.ibb.co/0yTwyRD/prothomalo-bangla-2024-07-c08a5bea-7a61-4a18-8dac-75fbc91eebdf-20240703-SH-0045064043.jpg', 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (23, 'চাকরিতে মুক্তিযোদ্ধা কোটা: হাইকোর্টের রায় স্থগিত হয়নি, আবেদনের শুনানি মুলতবি', 'https://www.prothomalo.com/bangladesh/zl8omh8ad4', 'সরকারি দপ্তর, স্বায়ত্তশাসিত বা আধা স্বায়ত্তশাসিত প্রতিষ্ঠান ও বিভিন্ন করপোরেশনের চাকরিতে সরাসরি নিয়োগের ক্ষেত্রে (৯ম থেকে ১৩তম গ্রেড) মুক্তিযোদ্ধা কোটা বাতিলের পরিপত্র অবৈধ ঘোষণার রায় স্থগিত হয়নি।', 'https://web.archive.org/web/20240705013727/https://www.prothomalo.com/bangladesh/zl8omh8ad4', 'https://i.ibb.co/rthxsgx/prothomalo-bangla-2023-09-97fc289e-1721-47f2-bf9f-fd25826ce190-prothomalo-bangla-2021-11-d5904e75-98.jpg', 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (24, 'সরকারি চাকরিতে কোটা বাতিলের দাবিতে শাহবাগ মোড় অবরোধ', 'https://www.prothomalo.com/bangladesh/gpyjbr61kg', 'সরকারি চাকরিতে কোটাব্যবস্থা বাতিল করে ২০১৮ সালে সরকারের জারি করা পরিপত্র পুনর্বহালের দাবিতে আজ বৃহস্পতিবারও আন্দোলন অব্যাহত রেখেছেন শিক্ষার্থী ও চাকরিপ্রত্যাশীরা। তাঁরা রাজধানীর শাহবাগ মোড় অবরোধ করেছেন। এতে শাহবাগ মোড় দিয়ে সব ধরনের যান চলাচল বন্ধ হয়ে গেছে। সৃষ্টি হচ্ছে যানজট।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/gpyjbr61kg', 'https://i.ibb.co/cK9dKMT/prothomalo-bangla-2024-07-463e867c-6e71-4625-988c-750e4bfc7ae5-5801a018-1c58-4f94-acbd-908d39f01cc2.jpg', 0, 1, '2024-08-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (25, 'কোটা বাতিলের দাবিতে রাবি শিক্ষার্থীদের সড়ক অবরোধ', 'https://www.prothomalo.com/video/bangladesh/52cfj6hujv', 'বৃষ্টির মধ্যেই আন্দোলনে শিক্ষার্থীরা। কোটা বাতিলের দাবিতে ঢাকা-রাজশাহী মহাসড়ক অবরোধ করেছেন রাজশাহী বিশ্ববিদ্যালয়ের শিক্ষার্থীরা।', 'https://youtu.be/ZMsV6BOYN2A', 'https://img.youtube.com/vi/ZMsV6BOYN2A/sddefault.jpg', 0, 1, '2024-08-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (26, 'কোটা বাতিলের দাবিতে জাহাঙ্গীরনগরে বিক্ষোভ, চতুর্থ দিনের মতো মহাসড়ক অবরোধ', 'https://www.prothomalo.com/bangladesh/district/025f35ax1e', 'সরকারি চাকরিতে কোটাপদ্ধতি বাতিল ও মেধাভিত্তিক নিয়োগের পরিপত্র বহাল রাখাসহ চার দাবিতে টানা চতুর্থ দিনের মতো ঢাকা-আরিচা মহাসড়ক অবরোধ করেছেন জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের শিক্ষার্থীরা।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/district/025f35ax1e', 'https://i.ibb.co/WvQqjxd/prothomalo-bangla-2024-07-c45d7562-d37d-4a12-ac94-c41ce9649bf8-JU-DH1642-20240704-IMG-20240704-12311.jpg', 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (27, 'কোটা বাতিলের দাবিতে বিভিন্ন সড়কে অবরোধ : ছবি গ্যালারি', 'https://www.prothomalo.com/photo/bangladesh/qg89lvk8jj', 'সরকারি চাকরিতে কোটাব্যবস্থা বাতিল করে ২০১৮ সালে সরকারের জারি করা পরিপত্র পুনর্বহালের দাবিতে আজ বৃহস্পতিবারও আন্দোলন চালিয়ে যাচ্ছেন শিক্ষার্থী ও চাকরিপ্রত্যাশীরা। তাঁরা রাজধানীর শাহবাগ মোড়, ঢাকা-চট্টগ্রাম মহাসড়ক, ঢাকা-আরিচা মহাসড়ক, রাজশাহী বিশ্ববিদ্যালয়ের প্রধান ফটকসহ বিভিন্ন জায়গায় অবস্থান নেন। ছবিতে থাকছে বিভিন্ন এলাকার আন্দোলনের চিত্র।', 'https://web.archive.org/web/0/https://www.prothomalo.com/photo/bangladesh/qg89lvk8jj', 'https://i.ibb.co/zb6TW83/prothomalo-bangla-2024-07-9fa03ac0-2a15-456d-a1a3-2106a9ea4a55-5.jpg', 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (28, 'কোটা বাতিলের দাবিতে মহাসড়কে আন্দোলনকারীদের অবস্থান', 'https://youtu.be/Kk5gCUVi8Ec', 'কোটা বাতিলের দাবিতে টানা চতুর্থ দিনের মতো ঢাকা-আরিচা মহাসড়ক অবরোধ করেছেন জাহাঙ্গীরনগর বিশ্ববিদ্যালয়ের শিক্ষার্থীরা। এদিকে ঢাকা-চট্টগ্রাম মহাসড়কের সদর দক্ষিণ উপজেলার কোটবাড়ী এলাকায় মহাসড়ক অবরোধ করে বিক্ষোভ করেছেন কুমিল্লা বিশ্ববিদ্যালয়ের শিক্ষার্থীরা।', 'https://youtu.be/Kk5gCUVi8Ec', 'https://img.youtube.com/vi/Kk5gCUVi8Ec/sddefault.jpg', 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (29, 'সরকারি চাকরিতে কোটা পুনর্বহালে ইউট্যাবের উদ্বেগ', 'https://www.prothomalo.com/bangladesh/snfpgj5c64', 'সরকারি চাকরিতে কোটাব্যবস্থা পুনর্বহাল হওয়ায় উদ্বেগ জানিয়েছে বিশ্ববিদ্যালয়শিক্ষকদের সংগঠন ইউনিভার্সিটি টিচার্স অ্যাসোসিয়েশন অব বাংলাদেশ (ইউট্যাব)। একই সঙ্গে কোটাপ্রথা বাতিলের দাবিতে শিক্ষার্থীদের চলমান আন্দোলনে সমর্থন জানিয়েছে সংগঠনটি।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/snfpgj5c64', 'https://i.ibb.co/cJPzdh8/prothomalo-bangla-2024-07-8b2a6dd3-4c8d-4d65-95db-15875efe5b85-2.jpg', 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (30, 'সরকারি চাকরিতে কোটা নিয়ে কী হচ্ছে', 'https://youtu.be/fAED-CYhgJc', '', 'https://web.archive.org/web/0/https://youtu.be/fAED-CYhgJc', 'https://img.youtube.com/vi/fAED-CYhgJc/sddefault.jpg', 0, 1, '2024-08-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (31, 'একাত্তরে জীবনযুদ্ধ করা সেসব মানুষের জন্য কোটা কই', 'https://www.prothomalo.com/opinion/reaction/mdfw51i0xl', 'একাত্তর সালের এক পরিবারের গল্প জানি—যুদ্ধের কিছু মাস আগে শারীরিক অসুস্থতায় পরিবারপ্রধান মারা গেছেন, মারা যাওয়ার সময় তাঁর পাঁচজন সন্তান রেখে যান। বড় তিন মেয়েকে এর আগে বিয়ে দেওয়া হয়েছে আর সন্তানদের মধ্যে যে সবচেয়ে ছোট, তার বয়স তখন চার বছর। এর মধ্যেই দেশে বেজে উঠল যুদ্ধের দামামা। এই পরিবার থেকে যুদ্ধে যাওয়ার জন্য উপযুক্ত কোনো সদস্য কি অবশিষ্ট ছিলেন?', 'https://web.archive.org/web/0/https://www.prothomalo.com/opinion/reaction/mdfw51i0xl', NULL, 0, 1, '2024-07-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (32, '''Mother, I am going to war''', 'https://www.tbsnews.net/bangladesh/mother-i-am-going-war-916981', 'It was the morning of 5 August, the day the Anti-Discrimination Student Movement had planned their "March to Dhaka" programme demanding the ouster of the Awami League government.

Shrabon intended to join the march.
Seeing his mother''s fear, Shrabon then reassured her with a lie, saying, "I''m just going to the canteen. Nowhere else."

It was the last time Shahnaz Begum would hear from her son in person.
Shrabon was killed when a bullet struck him in the head while participating in the March to Dhaka programme in Savar.

"I last spoke to Shrabon over the phone around 1:30pm that day. He told me he was in the Dairy Gate area, and I asked him to come home for lunch," Shahnaz said.
But he never returned home, she added, sobbing.
Md Shrabon Gazi, 20, was the son of Mannan Gazi and Shahnaz Begum from Gerua village in Savar, near Jahangirnagar University. He was the elder sibling of a sister.

He was studying software engineering at Tunku Abdul Rahman University of Management & Technology in Malaysia. He returned to the country on 16 July.
In 2022, he graduated from Savar Laboratory College with a GPA of 4.58 in his HSC exams. In February of this year, his family sent him to Malaysia for higher education.

Students who participated in the protests in Savar said Srabon was at the forefront of the march of students who started from Jahangirnagar University. After the march reached Savar, suddenly a bullet hit Shrabon in the head and he instantly fell on the ground.

He was immediately taken to Ashulia''s Public Health Society Medical College where the doctor on duty declared him dead.

"When the police began firing, their position was quite far from us. We moved towards Savar''s New Market, staying a bit behind the area where the gunfire was concentrated," Biplob Hossain, a 49th batch student of the Chemistry Department at Jahangirnagar University, told TBS.

"I was staying on the opposite side of the road from the Swaranika residential area, near Shimultala. Suddenly, there was a shout from the opposite direction that someone had been shot. It was Srabon," he added.

Shrabon''s father, Mannan Gazi, had worked in the garment sector for many years before leaving in 2016 to become a Breeding Assistant at Savar''s Central Cattle Breeding and Dairy Farm. Since then, the family has been living in the residential quarters of the dairy farm.

"We hoped that after completing his studies in software engineering, he would find a good job abroad or return to the country and contribute positively to the private sector," Mannan said.

"Shrabon returned to the country only 20 days before the incident. His semester hadn''t started yet. But as the movement escalated and lives were lost one after another, he couldn''t stay at home. In the end, he was killed as well," he added.

"After 2pm on 5 August, a boy called me and told me that Shrabon had been shot in the head. I immediately understood what had happened," Mannan Gazi said, bursting into tears.

Following Shrabon''s death, he was buried in the local cemetery of the Central Cattle Breeding and Dairy Farm area on the same day.

His death has cast a shadow of grief over the entire area. Locals want for a monument to be built to keep the memory of the by alive.', 'https://archive.ph/nu6Uq', 'https://i.ibb.co/phhNTFv/md-srabon-gazi-0.jpg', 1, 1, '2024-08-14');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (33, 'Bangladesh imposes curfew as protests continue', 'https://www.bbc.com/news/articles/cl4ymjrx10xo', 'Authorities in Bangladesh have imposed a nationwide curfew, after further rioting in the capital Dhaka left an additional 35 people dead.
Days of violence have been sparked by students calls for the government to axe a rule reserving scores of public jobs for the families of veterans of the country''s independence war in 1971.
The prime minister''s office announced the curfew after an attack on the Narsingdi prison on Friday saw hundreds of inmates released.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/cl4ymjrx10xo', 'https://i.ibb.co/4fFQf2Q/919cf660-45a8-11ef-af77-8713e5143fed-jpg.webp', 0, 1, '2024-07-20');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (34, 'UAE jails 57 Bangladeshis over protests against own government', 'https://www.bbc.com/news/articles/crgk8gnpg0zo', 'A court in the United Arab Emirates has handed 57 Bangladeshis long prison terms for holding protests in the Gulf state against their own country’s government.
Three of the unnamed defendants were sentenced to life for “inciting riots in several streets across the UAE on Friday”, while 53 others were jailed for 10 years and one for 11 years, state-run Wam news agency reported.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/crgk8gnpg0zo', 'https://i.ibb.co/L1RXBtc/e836a6a0-481a-11ef-9e1c-3b4a473456a6-jpg.webp', 0, 1, '2024-07-23');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (35, 'Drenched in blood - how Bangladesh protests turned deadly', 'https://www.bbc.com/news/articles/c4ng5v03gd4o', 'Anti-government protests have sparked nationwide clashes in Bangladesh between police and university students. At least 150 people have been killed - and some of those caught up in the bloodshed have described to the BBC what happened.
One student said demonstrators in the capital Dhaka just wanted to hold a peaceful rally, but the police "ruined" it by attacking them as they were gathering.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/c4ng5v03gd4o', 'https://i.ibb.co/yV4LKnZ/5e867400-4917-11ef-a168-7982b5cfc27f-jpg.webp', 1, 1, '2024-07-24');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (36, 'How Bangladesh''s protests ended Sheikh Hasina''s 15-year reign', 'https://www.bbc.com/news/articles/c9033zpv0nvo', 'The words had become a rallying cry for young Bangladeshis in recent weeks - and on Monday their fury ended the prime minister''s 15-year reign.
The 76-year-old Ms Hasina had ruled the South Asian nation of 170 million with an iron fist since 2009 - just a month ago, protests demanding her resignation would have been unthinkable.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/c9033zpv0nvo', 'https://i.ibb.co/WcnjG5M/daa3fba0-5300-11ef-ae88-471f4b2d8884-jpg-1.webp', 0, 1, '2024-08-05');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (37, 'Dozens of children killed in Bangladesh protests - Unicef', 'https://www.bbc.com/news/articles/c16j6w1dxl1o', 'At least 32 children have died during student protests that engulfed Bangladesh last month, the UN''s children''s agency has said.
The youngest child killed had yet to turn five years old, a Unicef spokesperson said, adding that most of those who died were bystanders.
They were among more than 200 people who were killed during demonstrations against job quotas in the civil service, according to figures verified by BBC Bangla.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/c16j6w1dxl1o', 'https://i.ibb.co/T4MXNSm/ba40c660-50d8-11ef-b2d2-cdb23d5d7c5b-jpg.webp', 1, 1, '2024-08-02');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (38, 'Videos reveal brutality that left scores dead in Bangladesh protests', 'https://www.bbc.com/news/articles/c720lzejzwpo', 'An image is worth a thousand words – sometimes, it can even stir a nation.
In Bangladesh, it was the image of university student Abu Sayeed standing with open arms, stick in hand, facing heavily-armed police alone which many credit as the turning point in the recent widespread protest in the country against quotas in government jobs.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/c720lzejzwpo', 'https://i.ibb.co/4TYNXFF/408d8da0-4db6-11ef-aebc-6de4d31bf5cd-jpg.webp', 1, 1, '2024-07-30');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (39, 'Bangladesh police detain protest leaders at hospitalBangladesh police detain protest leaders at hospital', 'https://www.bbc.com/news/articles/c6p21g8863no', 'Three student protest leaders who helped co-ordinate the recent rallies in Bangladesh have been forcibly removed from hospital by police officers, the BBC understands.
Nahid Islam, Asif Mahmud and Abu Baker Majumder were taken from Gonoshasthaya Hospital in the capital, Dhaka, hospital staff said on Friday.
Staff members said the officers, who were dressed in plainclothes, had forced their discharge despite the misgivings of medics at the hospital.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/c6p21g8863no', 'https://i.ibb.co/vsDQWFk/4438c610-4b6b-11ef-9dde-8160ee3d931b-png.webp', 0, 1, '2024-07-26');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (40, 'Bangladesh''s ex-PM investigated for murder', 'https://www.bbc.com/news/articles/c3ej1205l3wo', 'A murder investigation has been opened into Bangladesh''s former prime minister Sheikh Hasina over the police killing of a man during civil unrest.
Six other top figures in the previous government are also being investigated following weeks of deadly unrest in the capital Dhaka.
Ms Hasina resigned earlier this month, fleeing to neighbouring India, as calls grew for her to stand down.', 'https://web.archive.org/web/0/https://www.bbc.com/news/articles/c3ej1205l3wo', 'https://i.ibb.co/5WSXynv/08e6bfc0-595f-11ef-babd-c9f9720e8cad-jpg.webp', 0, 1, '2024-08-13');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (41, 'আপনাদের কী হবে তা আমার পরিবারের চিন্তার বিষয় না: সজীব ওয়াজেদ জয়', 'https://jamuna.tv/news/553462', 'শেখ হাসিনার পদত্যাগের পর বাংলাদেশ আওয়ামী লীগের অফিশিয়াল পেজ থেকে ভিডিও বার্তা দিয়েছেন তার পুত্র সজীব ওয়াজেদ জয়। সোমবার (৫ আগস্ট) বেলা ২টায় এই ভিডিও প্রকাশ করা হয়। ধারণা করা হচ্ছে, শেখ হাসিনা পদত্যাগ করবেন, এমনটা আঁচ করেই এই ভিডিও আগে থেকে রেকর্ড করা হয়েছিল।', 'https://web.archive.org/web/0/https://jamuna.tv/news/553462', 'https://i.ibb.co/k2njYqd/joy-news-3.jpg', 0, 1, '2024-08-05');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (42, 'আজ থেকে সর্বাত্মক অসহযোগ আন্দোলন', 'https://jamuna.tv/news/553182', 'এক দফা দাবির ডাক দিয়েছে ছাত্র আন্দোলন। এই এক দফা বাস্তবায়নে আজ রোববার (৪ আগস্ট) থেকে সর্বাত্মক অসহযোগ আন্দোলনের ঘোষণা দেওয়া হয়েছে। গতকাল শনিবার রাজধানীর কেন্দ্রীয় শহীদ মিনার পাদদেশে এ ঘোষণা দেন বৈষম্যবিরোধী ছাত্র আন্দোলনের সমন্বয়ক নাহিদ ইসলাম।', 'https://web.archive.org/web/0/https://jamuna.tv/news/553182', 'https://i.ibb.co/8rD2j1h/1-dofa.jpg', 0, 1, '2024-08-04');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (43, '৭৮ এইচএসসি পরীক্ষার্থীর জামিন, কারামুক্ত ৩৫', 'https://jamuna.tv/news/552901', 'দেশের বিভিন্ন আদালত থেকে এইচএসসির ৭৮ পরীক্ষার্থীকে জামিন দেয়া হয়েছে। এদিকে রাতেই যাচাই বাছাই শেষে কেরাণীগঞ্জ কেন্দ্রীয় কারাগার থেকে ৩৫ শিক্ষার্থীকে ছেড়ে দেয়া হয়।

শুক্রবার (২ আগস্ট) সাপ্তাহিক ছুটির দিনে তাদের জামিন দেয়া হয়। জামিনপ্রাপ্তদের মধ্যে ঢাকা বিভাগের ৫৫ জন চট্টগ্রাম বিভাগে ১৪, খুলনা বিভাগে ৬ এবং রংপুর বিভাগে ৬ জন। কোটা সংস্কার আন্দোলনকে কেন্দ্র করে চলমান সহিংসতা ও নাশকতার ঘটনায় তাদের গ্রেফতার করা হয়। পরীক্ষার কথা বিবেচনায় নিয়ে আইনমন্ত্রী আনিসুল হকের উদ্যোগে তাদের জামিন দেয়া হয়।', 'https://web.archive.org/web/0/https://jamuna.tv/news/552901', 'https://i.ibb.co/MNQNrK0/JAmin.jpg', 0, 1, '2024-08-02');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (44, 'মির্জাপুরে ছাত্রলীগের হামলায় বৈষম্যবিরোধী আন্দোলনের ৩ সমন্বয়ক আহত, আটক ১', 'https://www.prothomalo.com/bangladesh/district/717mjs2ufy', 'টাঙ্গাইলের মির্জাপুর উপজেলায় ছাত্রলীগের নেতা-কর্মীদের হামলায় বৈষম্যবিরোধী ছাত্র আন্দোলনের তিন সমন্বয়ক আহত হয়েছেন। আজ বৃহস্পতিবার দুপুরে উপজেলার শহীদ ভবানী প্রসাদ সাহা সরকারি কলেজে এ ঘটনা ঘটে।

আহত সমন্বয়কেরা হলেন মোজাহিদুল ইসলাম (১৮), ইমন সিদ্দিকী (২৩) ও জাকির হোসেন (২৪)।', 'https://web.archive.org/web/0/https://www.prothomalo.com/bangladesh/district/717mjs2ufy', 'https://i.ibb.co/5LSsGxV/prothomalo-bangla-2024-08-15-dhei9q3w-Tangail.webp', 0, 1, '2024-08-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (45, 'ঢাবির রোকেয়া হলের মেইন গেট ভেঙে রাস্তায় ছাত্রীরা', 'https://thedailycampus.com/universities/147436/%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%B0%E0%A7%8B%E0%A6%95%E0%A7%87%E0%A7%9F%E0%A6%BE-%E0%A6%B9%E0%A6%B2%E0%A7%87%E0%A6%B0-%E0%A6%AE%E0%A7', 'প্রধানমন্ত্রী শেখ হাসিনার একটি বক্তব্যকে কেন্দ্র করে ফের উত্তপ্ত ঢাকা বিশ্ববিদ্যালয় ক্যাম্পাস। এরই জেরে আজ রবিবার রাত ১১টার দিকে বিক্ষোভের ডাক দেয়া হয়েছে। এর আগে বিভিন্ন আবাসিক হল থেকে শিক্ষার্থীরা মিছিল নিয়ে টিএসসির রাজু ভাস্কর্যের পাদদেশে জড়ো হতে দেখা গেছে।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147436/%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%B0%E0%A7%8B%E0%A6%95%E0%A7%87%E0%A7%9F%E0%A6%BE-%E0%A6%B9%E0%A6%B2%E0%A7%87%E0%A6%B0-%E0%A6%AE%E0%A7', 'https://i.ibb.co/sHvHMBM/147436-144.jpg', 0, 1, '2024-07-14');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (46, 'এফ রহমান হলে ছয় শিক্ষার্থীকে ছাত্রলীগের মারধর, তিনজনকে হল ছাড়া', 'https://thedailycampus.com/universities/147568/%E0%A6%8F%E0%A6%AB-%E0%A6%B0%E0%A6%B9%E0%A6%AE%E0%A6%BE%E0%A6%A8-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%9B%E0%A7%9F-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A', 'কোটা সংস্কার আন্দোলনে যাওয়ার ও ছবি পোস্ট করায় ঢাকা বিশ্ববিদ্যালয়ের স্যার এ এফ রহমান হলের ছয় শিক্ষার্থীকে বেধড়ক মারধর করেছে সংগঠনটির পদপ্রত্যাশী নেতাকর্মীরা। এদের মধ্যে তিনজনকে হল থেকে বের করে দেওয়া হয়েছে। সোমবার (১৫ জুলাই) বিভিন্ন সময়ে এসব মারধরের ঘটনা ঘটে।

মারধরের শিকার শিক্ষার্থীরা হলেন- ২০২০-২১ সেশনের আব্দুল বাসিত, শাকাওয়াত হোসেন সাকু, লিমন খান রানা, মোর্শেদ ইসলাম। ২০১৬-১৭ সেশনের ফারুক ও তাওহীদ ইসলাম।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147568/%E0%A6%8F%E0%A6%AB-%E0%A6%B0%E0%A6%B9%E0%A6%AE%E0%A6%BE%E0%A6%A8-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%9B%E0%A7%9F-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A', 'https://i.ibb.co/G7NWM0s/147568-119.jpg', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (47, 'ছাত্রলীগের হামলায় দুই শতাধিক আহত', 'https://tinyurl.com/4wnk4f5s', 'ঢাকা বিশ্ববিদ্যালয়ে দিনভর ছাত্রলীগের হামলায় দুই শতাধিক আহত হয়েছেন বলে জানিয়েছেন কোটা সংষ্কার আন্দোলনের সমন্বয়ক নাহিদুল ইসলাম। 

আজ সোমবার রাত ৯.৩০ ঢাকা বিশ্ববিদ্যালয়ের কার্জন হলে এক সংবাদ সম্মেলনে তিনি এ কথা বলেন। 

সংবাদ সম্মেলনে সমন্বয়ক নাহিদ ইসলাম বলেন, এ হামলা পরিকল্পিতভাবে হয়েছে। সরকার এ আন্দোলন সহিংসভাবে বন্ধের চেষ্টা করছে। প্রধানমন্ত্রীর বক্তব্য প্রত্যাহারের দাবি জানিয়ে তিনি জানান, আগামীকাল বিকেল ৩.০০ টায় দেশের সব ক্যাম্পাসে বিক্ষোভ মিছিল করা হবে আন্দোলনরত শিক্ষার্থীদের পক্ষ থেকে। এরপর চলমান অবরোধ কর্মসূচিও পালন করা হবে।', 'https://web.archive.org/web/0/https://tinyurl.com/4wnk4f5s', 'https://i.ibb.co/CHvn88D/147558-150-1.jpg', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (48, 'ঢাবি শিক্ষার্থীদের পেটাতে টিএসসিতে বেসরকারি বিশ্ববিদ্যালয়ের বহিষ্কৃত ছাত্র', 'https://thedailycampus.com/student-movement-politics/147555/%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%A6%E0%', 'কোটা সংস্কারপন্থীদের চলমান আন্দোলনে সাধারণ শিক্ষার্থীদের থামাতে মাঠে নেমেছে ক্ষমতাসীন আওয়ামী লীগের ছাত্রসংগঠন ছাত্রলীগ। সংগঠনটির সভাপতি চলমান আন্দোলনটিকে রাজনৈতিকভাবে মোকাবেলা করার ঘোষণা দিয়েছেন। সোমবার (১৫ জুলাই) আন্দোলনরত শিক্ষার্থীদের সাথে দফায় দফায় সংঘর্ষে জড়িয়েছে ছাত্রলীগের নেতাকর্মীরা।', 'https://web.archive.org/web/0/https://thedailycampus.com/student-movement-politics/147555/%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%A6%E0%', 'https://i.ibb.co/VTCSRcV/147555-174.jpg', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (49, 'কোটা সংস্কার আন্দোলনে তিতুমীর কলেজের আহত ৭', 'https://thedailycampus.com/public-university/147548/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%B8%E0%A6%82%E0%A6%B8%E0%A7%8D%E0%A6%95%E0%A6%BE%E0%A6%B0-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E', 'ঢাকা বিশ্ববিদ্যালয় এলাকায় কোটা সংস্কারের দাবিতে আন্দোলনরত শিক্ষার্থীদের ওপর ছাত্রলীগের হামলায় অন্তত ৮০ জন শিক্ষার্থী আহত হয়েছেন। তিতুমীর কলেজের শিক্ষার্থীরাও এই হামলায় আহত হন। সোমবার (১৫ জুলাই) বিকেলে আহতদের উদ্ধার করে ঢাকা মেডিকেল কলেজ (ঢামেক) হাসপাতালের জরুরি বিভাগে নিয়ে আসা হয়।', 'https://web.archive.org/web/0/https://thedailycampus.com/public-university/147548/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%B8%E0%A6%82%E0%A6%B8%E0%A7%8D%E0%A6%95%E0%A6%BE%E0%A6%B0-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E', 'https://i.ibb.co/gSyR9Sw/147548-15.jpg', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (50, 'ঢামেকে শিক্ষার্থীদের ওপর ছাত্রলীগের হামলা', 'https://tinyurl.com/45js56xc', 'ঢাকা মেডিকেল কলেজ হাসপাতালে (ঢামেক) চিকিৎসাধীন আন্দোলনকারীদের ওপর হামলা করেছে ছাত্রলীগ। সোমবার (১৫ জুলাই) সন্ধ্যায় মেডিকেলের ভেতরে ঢুকে ছাত্রলীগ এ হামলা চালায় বলে অভিযোগ পাওয়া যায়। 

সরেজমিনে দেখা যায়, হাসপাতালের ভেতরে লাঠি-সোটাসহ ছাত্রলীগের কর্মীরা ঢুকে চিকিৎসাধীন শিক্ষার্থীদের ওপর হামলা চালায়। পরবর্তীতে পুলিশ এবং আনসার সদস্যরা এসে পরিস্থিতি নিয়ন্ত্রণে আনার চেষ্টা চালায়। হামলা চলাকালে তাদের বিরুদ্ধে সাধারণ শিক্ষার্থীদের হাসপাতাল থেকে বের করে দেওয়ার অভিযোগ ওঠে।', 'https://web.archive.org/web/0/https://tinyurl.com/45js56xc', 'https://i.ibb.co/9hW2M7w/147544-124.jpg', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (51, 'চুয়েটের বাসে ঢুকে ছাত্রীদের পেটাল ছাত্রলীগ, ৩০ জন আহত', 'https://thedailycampus.com/engineering-university/147696/%E0%A6%9A%E0%A7%81%E0%A7%9F%E0%A7%87%E0%A6%9F%E0%A7%87%E0%A6%B0-%E0%A6%AC%E0%A6%BE%E0%A6%B8%E0%A7%87-%E0%A6%A2%E0%A7%81%E0%A6%95%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%AA%E0%A7%87%E0%A6%9F%E0%A6%BE%E0%A6%B2-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97-%E0%A7%A9%E0%A7%A6-%E0%A6%9C%E0%A6%A8-%E0%A6%86%E0%A6%B9%E0%A6%A4', 'চট্টগ্রাম প্রকৌশল ও প্রযুক্তি বিশ্ববিদ্যালয়ের (চুয়েট) বাসে হামলা চালিয়েছে ছাত্রলীগ। এসময় বাসে থাকা নারী শিক্ষার্থীদের উপর হামলা করা হয় বলে অভিযোগ করেছে শিক্ষার্থীরা। আজ (মঙ্গলবার) রাত ৯ ঘটিকায় চট্টগ্রামের চাদগাঁও আবাসিক এলাকায় অবস্থানরত সাঙ্গু বাসে এ হামলা চালানো হয়।', 'https://web.archive.org/web/0/https://thedailycampus.com/engineering-university/147696/%E0%A6%9A%E0%A7%81%E0%A7%9F%E0%A7%87%E0%A6%9F%E0%A7%87%E0%A6%B0-%E0%A6%AC%E0%A6%BE%E0%A6%B8%E0%A7%87-%E0%A6%A2%E0%A7%81%E0%A6%95%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%AA%E0%A7%87%E0%A6%9F%E0%A6%BE%E0%A6%B2-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97-%E0%A7%A9%E0%A7%A6-%E0%A6%9C%E0%A6%A8-%E0%A6%86%E0%A6%B9%E0%A6%A4', 'https://i.ibb.co/cLRXb6Q/147696-199.jpg', 0, 1, '2024-07-16');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (52, 'বেরোবিতে কোটা আন্দোলনকারীদের উপর ছাত্রলীগের হামলা', 'https://thedailycampus.com/student-movement-politics/147197/%E0%A6%AC%E0%A7%87%E0%A6%B0%E0%A7%8B%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0', 'রংপুরের বেগম রোকেয়া বিশ্ববিদ্যালয়ে (বেরোবি) কোটা সংস্কারপন্থি শিক্ষার্থীদের উপর হামলা করেছে ছাত্রলীগের নেতাকর্মীরা। ‍বৃহস্পতিবার (১১ জুলাই ২০২৪) বিকাল সাড়ে ৪ টায় এ ঘটনা ঘটে।', 'https://web.archive.org/web/0/https://thedailycampus.com/student-movement-politics/147197/%E0%A6%AC%E0%A7%87%E0%A6%B0%E0%A7%8B%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0', 'https://i.ibb.co/1JnB461/147197-157.jpg', 0, 1, '2024-07-11');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (53, 'আন্দোলনের নামে অস্থিতিশীলতার চেষ্টা করলে ভালো হবে না: ইনান', 'https://thedailycampus.com/student-movement-politics/147334/%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87%E0%A6%B0-%E0%A6%A8%E0%A6%BE%E0%A6%AE%E0%A7%87-%E0%A6%85%E0%A6%B8%E0', 'ছাত্রলীগের সাধারণ সম্পাদক শেখ ওয়ালী আসিফ ইনান বলেছেন, যারা শিক্ষার্থীদের ঘাড়ে ভর করে ষড়যন্ত্র করে এ দেশের অগ্রযাত্রাকে বিঘ্নিত করার চেষ্টা করে, সেই ধরনের লোকদের এ আন্দোলনে সম্পৃক্ততা আমাদের উদ্বিগ্ন করে। কোটা সংস্কার আন্দোলনের নামে কেউ দেশের শান্ত পরিবেশকে অস্থিতিশীল করার চেষ্টা করলে ফলাফল ভালো হবে না।', 'https://web.archive.org/web/0/https://thedailycampus.com/student-movement-politics/147334/%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87%E0%A6%B0-%E0%A6%A8%E0%A6%BE%E0%A6%AE%E0%A7%87-%E0%A6%85%E0%A6%B8%E0', 'https://i.ibb.co/qC40fqr/147334-185.jpg', 0, 1, '2024-07-13');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (54, 'কাল সারাদেশে ‘কমপ্লিট শাটডাউন’ ঘোষণা কোটা আন্দোলনকারীদের', 'https://thedailycampus.com/universities/147836/%E0%A6%95%E0%A6%BE%E0%A6%B2-%E0%A6%B8%E0%A6%BE%E0%A6%B0%E0%A6%BE%E0%A6%A6%E0%A7%87%E0%A6%B6%E0%A7%87-%E0%A6%95%E0%A6%AE%E0%A6%AA%E0%A7%8D%E0%A6%B2%E0%A6%BF%E0%A6%9F-%E0%A6%B6%E0%A6%BE%E0%A6%9F%E0%A6%A1%E0%A6%BE%E0%A6%89%E0%A6%A8-%E0%A6%98%E0%A7%8B%E0%A6%B7%E0%A6%A3%E0%A6%BE-%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A6%95%E0%A6%BE%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0', 'শিক্ষার্থীদের শান্তিপূর্ণ আন্দোলনে ওপর পুলিশ, বিজিবি, র‍্যাবের হামলা, খুনের প্রতিবাদ, খুনিদের বিচার, সন্ত্রাসমুক্ত ক্যাম্পাস নিশ্চিত ও এক দফা দাবিতে আগামীকাল বৃহস্পতিবার (১৮ জুলাই) সারাদেশে ‘কমপ্লিট শাটডাউন’ ঘোষণা করেছে কোটা সংস্কার আন্দোলনরত শিক্ষার্থীদের প্ল্যাটফর্ম ‘বৈষম্যবিরোধী ছাত্র আন্দোলন’। আজ বুধবার (১৭ এপ্রিল) রাত ৮টার দিকে এক বিবৃতিতে এ তথ্য জানানো হয়।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147836/%E0%A6%95%E0%A6%BE%E0%A6%B2-%E0%A6%B8%E0%A6%BE%E0%A6%B0%E0%A6%BE%E0%A6%A6%E0%A7%87%E0%A6%B6%E0%A7%87-%E0%A6%95%E0%A6%AE%E0%A6%AA%E0%A7%8D%E0%A6%B2%E0%A6%BF%E0%A6%9F-%E0%A6%B6%E0%A6%BE%E0%A6%9F%E0%A6%A1%E0%A6%BE%E0%A6%89%E0%A6%A8-%E0%A6%98%E0%A7%8B%E0%A6%B7%E0%A6%A3%E0%A6%BE-%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A6%95%E0%A6%BE%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0', 'https://i.ibb.co/HT3SFQP/147836-149.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (55, 'শাবিপ্রবির হলে ছাত্রলীগের রুম থেকে আগ্নেয়াস্ত্রসহ বিদেশি মদ উদ্ধার', 'https://thedailycampus.com/engineering-university/147830/%E0%A6%B6%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%AA%E0%A7%8D%E0%A6%B0%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6', 'আগ্নেয়াস্ত্র, দেশীয় অস্ত্র ও বিশাল পরিমাণে বিদেশি মদ ও গাঁজার সন্ধান মিলেছে শাহজালাল বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয় (শাবিপ্রবি) শাহপরান হলের ছাত্রলীগের রুমে। বুধবার (১৭ জুলাই) বিশ্ববিদ্যালয়ের কয়েকজন শিক্ষার্থী ছাত্রলীগ নেতাদের রুম অনুসন্ধান করে পায়।', 'https://web.archive.org/web/0/https://thedailycampus.com/engineering-university/147830/%E0%A6%B6%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%AA%E0%A7%8D%E0%A6%B0%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6', 'https://i.ibb.co/NFXTcwR/147830-131.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (56, 'ভিসির অনুমতিক্রমে ঢাবির মিছিল ছত্রভঙ্গ করা হয়েছে: পুলিশ', 'https://thedailycampus.com/universities/147816/%E0%A6%AD%E0%A6%BF%E0%A6%B8%E0%A6%BF%E0%A6%B0-%E0%A6%85%E0%A6%A8%E0%A7%81%E0%A6%AE%E0%A6%A4%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B0%E0%A6%AE%E0%A7%87-%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%AE%E0%A6%BF%E0%A6%9B%E0%A6%BF%E0%A6%B2-%E0%A6%9B%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%AD%E0%A6%99%E0%A7%8D%E0%A6%97-%E0%A6%95%E0%A6%B0%E0%A6%BE-%E0%A6%B9%E0%A7%9F%E0%A7%87%E0%A6%9B%E0%A7%87-%E0%A6%AA%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%B6', 'ঢাকা বিশ্ববিদ্যালয়ে কোটা সংস্কার আন্দোলনকারী শিক্ষার্থীদের সঙ্গে পুলিশের সংঘর্ষ চলছে। আজ বুধবার (১৭ জুলাই) বিকেল সোয়া ৪টায় এ সংঘর্ষ শুরু হয়। এর আগে বিশ্ববিদ্যালয়ের উপাচার্য বাসভবন থেকে শিক্ষার্থীরা একটি মিছিল নিয়ে টিএসসির দিকে অগ্রসর হলে পুলিশ সাউন্ড গ্রেনেড, রাবার বুলেট ও টিয়ারশেল ছোড়ে। এসময় শিক্ষার্থীরাও ইটপাটকেল ছুড়তে থাকেন।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147816/%E0%A6%AD%E0%A6%BF%E0%A6%B8%E0%A6%BF%E0%A6%B0-%E0%A6%85%E0%A6%A8%E0%A7%81%E0%A6%AE%E0%A6%A4%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B0%E0%A6%AE%E0%A7%87-%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%AE%E0%A6%BF%E0%A6%9B%E0%A6%BF%E0%A6%B2-%E0%A6%9B%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%AD%E0%A6%99%E0%A7%8D%E0%A6%97-%E0%A6%95%E0%A6%B0%E0%A6%BE-%E0%A6%B9%E0%A7%9F%E0%A7%87%E0%A6%9B%E0%A7%87-%E0%A6%AA%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%B6', 'https://i.ibb.co/23kyBYZ/147816-175.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (57, 'ফের ঢাবিতে আন্দোলনকারীদের ওপর সাউন্ড গ্রেনেড, উত্তেজনা শুরু', 'https://thedailycampus.com/universities/147795/%E0%A6%AB%E0%A7%87%E0%A6%B0-%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A6%', 'ঢাবি ভিসি চত্বরে জড়ো হওয়া কোটা সংস্কার আন্দোলনকারীরা কফিন মিছিল নিয়ে টিএসসিতে যাওয়ার সময় পুলিশের সাউন্ড গ্রেনেড নিক্ষেপের ঘটনা ঘটেছে। এ ঘটনাকে কেন্দ্র করে দুপক্ষের মধ্যে উত্তেজনা শুরু হয়েছে। 

বুধবার (১৭ জুলাই) বিকেল ৪ টার দিকে এ ঘটনা ঘটে।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147795/%E0%A6%AB%E0%A7%87%E0%A6%B0-%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A6%', 'https://i.ibb.co/Ws3c5W3/147795-18.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (58, 'ফেনীতে কোটা আন্দোলনকারীদের বিক্ষোভে ছাত্রলীগের হামলা, আহত ২০', 'https://thedailycampus.com/universities/147795/%E0%A6%AB%E0%A7%87%E0%A6%B0-%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A6%95%E0%A6%BE%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%93%E0%A6%AA%E0%A6%B0-%E0%A6%B8%E0%A6%BE%E0%A6%89%E0%A6%A8%E0%A7%8D%E0%A6%A1-%E0%A6%97%E0%A7%8D%E0%A6%B0%E0%A7%87%E0%A6%A8%E0%A7%87%E0%A6%A1-%E0%A6%89%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A7%87%E0%A6%9C%E0%A6%A8%E0%A6%BE-%E0%A6%B6%E0%A7%81%E0%A6%B0%E0%A7%81#:~:text=%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%20%E0%A6%AD%E0%A6%BF%E0%A6%B8%E0%A6%BF%20%E0%A6%9A%E0%A6%A4%E0%A7%8D%E0%A6%AC%E0%A6%B0%E0%A7%87%20%E0%A6%9C%E0%A6%A1%E0%A6%BC%E0%A7%8B%20%E0%A6%B9%E0%A6%93%E0%A6%AF%E0%A6%BC%E0%A6%BE,%E0%A6%9F%E0%A6%BE%E0%A6%B0%20%E0%A6%A6%E0%A6%BF%E0%A6%95%E0%A7%87%20%E0%A6%8F%20%E0%A6%98%E0%A6%9F%E0%A6%A8%E0%A6%BE%20%E0%A6%98%E0%A6%9F%E0%A7%87%E0%A5%A4', 'ফেনীতে কোটা আন্দোলনকারী সাধারণ শিক্ষার্থীদের প্রতিবাদ মিছিলে হামলা করেছেন ছাত্রলীগ নেতাকর্মীরা। বুধবার (১৭ জুলাই) শহরের ট্রাংক রোডে এ ঘটনা ঘটে। এ সময় সংঘর্ষে ২০ জন আহত হয়েছেন।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147795/%E0%A6%AB%E0%A7%87%E0%A6%B0-%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A6%95%E0%A6%BE%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%93%E0%A6%AA%E0%A6%B0-%E0%A6%B8%E0%A6%BE%E0%A6%89%E0%A6%A8%E0%A7%8D%E0%A6%A1-%E0%A6%97%E0%A7%8D%E0%A6%B0%E0%A7%87%E0%A6%A8%E0%A7%87%E0%A6%A1-%E0%A6%89%E0%A6%A4%E0%A7%8D%E0%A6%A4%E0%A7%87%E0%A6%9C%E0%A6%A8%E0%A6%BE-%E0%A6%B6%E0%A7%81%E0%A6%B0%E0%A7%81#:~:text=%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%20%E0%A6%AD%E0%A6%BF%E0%A6%B8%E0%A6%BF%20%E0%A6%9A%E0%A6%A4%E0%A7%8D%E0%A6%AC%E0%A6%B0%E0%A7%87%20%E0%A6%9C%E0%A6%A1%E0%A6%BC%E0%A7%8B%20%E0%A6%B9%E0%A6%93%E0%A6%AF%E0%A6%BC%E0%A6%BE,%E0%A6%9F%E0%A6%BE%E0%A6%B0%20%E0%A6%A6%E0%A6%BF%E0%A6%95%E0%A7%87%20%E0%A6%8F%20%E0%A6%98%E0%A6%9F%E0%A6%A8%E0%A6%BE%20%E0%A6%98%E0%A6%9F%E0%A7%87%E0%A5%A4', 'https://i.ibb.co/ypwhhM2/147792-113.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (59, 'আন্দোলনে না যেতে ছাত্রীদের হলে আটকে রাখলেন ছাত্রলীগ নেত্রী', 'https://thedailycampus.com/public-university/147777/%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%A8%E0%A6%BE-%E0%A6%AF%E0%A7%87%E0%A6%A4%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%86%E0%A6%9F%E0%A6%95%E0%A7%87-%E0%A6%B0%E0%A6%BE%E0%A6%96%E0%A6%B2%E0%A7%87%E0%A6%A8-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97-%E0%A6%A8%E0%A7%87%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A7%80', 'রাজধানীর সরকারি তিতুমীর কলেজের সুফিয়া কামাল ছাত্রীনিবাসে বেশ কয়েজন ছাত্রীকে আটকে রাখার অভিযোগ উঠেছে কলেজ শাখা ছাত্রলীগের উপ-ছাত্রী বিষয়ক সম্পাদক সাবিকুন্নাহার মুক্তার বিরুদ্ধে। ছাত্রীদের অভিযোগ, চলমান কোটা আন্দোলনে গেলে মুক্তা ছাত্রলীগ নেতাদের দিয়ে তাদের ব্যবস্থা নেওয়ার হুমকিও দিয়েছেন।', 'https://web.archive.org/web/0/https://thedailycampus.com/public-university/147777/%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%A8%E0%A6%BE-%E0%A6%AF%E0%A7%87%E0%A6%A4%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%86%E0%A6%9F%E0%A6%95%E0%A7%87-%E0%A6%B0%E0%A6%BE%E0%A6%96%E0%A6%B2%E0%A7%87%E0%A6%A8-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97-%E0%A6%A8%E0%A7%87%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A7%80', 'https://i.ibb.co/hYWGckd/147777-198.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (60, 'ঢাবির হলে ছাত্রলীগ নেতার রুম থেকে অস্ত্র উদ্ধার', 'https://thedailycampus.com/universities/147741/%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97-%E0%A6', 'ঢাকা বিশ্ববিদ্যালয়ের (ঢাবি) মাস্টার দা সূর্য সেন হলে ছাত্রলীগের নেতাদের রুমে ভাঙচুর চালিয়েছে সাধারণ শিক্ষার্থীরা। আজ বুধবার সকালে এই ভাঙচুর চালায়।

এসময় হলের ৪৪০নং রুম থেকে একটি অস্ত্র উদ্ধার করেছে তারা। পরে সেটি হল প্রভোস্ট অধ্যাপক ড. জাকির হোসেন ভূইয়ার কাছে জমা দেন তারা।', 'https://web.archive.org/web/0/https://thedailycampus.com/universities/147741/%E0%A6%A2%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0-%E0%A6%B9%E0%A6%B2%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97-%E0%A6', 'https://i.ibb.co/F8TTBnb/147741-114.jpg', 0, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (61, 'শেষ পর্যন্ত নিজেই একজন ‘শামসুজ্জোহা’ হয়ে মারা গেলেন', 'https://thedailycampus.com/public-university/147700/%E0%A6%B6%E0%A7%87%E0%A6%B7-%E0%A6%AA%E0%A6%B0%E0%A7%8D%E0%A6%AF%E0%A6%A8%E0%A7%8D%E0%A6%A4-%E0%A6%A8%E0%A6%BF%E0%A6%9C%E0%A7%87%E0%A6%87-%E0%A6%8F%', 'পুলিশের গুলিতে আবু সাইদ নামে বেগম রোকেয়া বিশ্ববিদ্যালয়ের (বেরোবি) কোটা সংস্কার আন্দোলনের এক সমন্বয়ক নিহত হয়েছেন। তার শরীরে ছররা গুলির অসংখ্য চিহ্ন পাওয়া যায়। মৃত্যুর আগের দিন তিনি গত সোমবার (১৫ জুলাই) নিজের ফেসবুক প্রোফাইলে বাঙালি শিক্ষাবিদ ও অধ্যাপক সৈয়দ মোহাম্মদ শামসুজ্জোহার একটি ঐতিহাসিক উক্তি সংবলিত ছবি শেয়ার করেছেন। যে পোস্টে আবু সাইদ শিক্ষক শামসুজ্জোহার মতো মৃত্যু কামনা করেন। যা ইতিমধ্যে সামাজিক যোগাযোগমাধ্যমে ভাইরাল।', 'https://web.archive.org/web/0/https://thedailycampus.com/public-university/147700/%E0%A6%B6%E0%A7%87%E0%A6%B7-%E0%A6%AA%E0%A6%B0%E0%A7%8D%E0%A6%AF%E0%A6%A8%E0%A7%8D%E0%A6%A4-%E0%A6%A8%E0%A6%BF%E0%A6%9C%E0%A7%87%E0%A6%87-%E0%A6%8F%', 'https://i.ibb.co/2c5y8QB/147700-187.jpg', 1, 1, '2024-07-17');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (62, 'গুলিবিদ্ধ, আহতদের নিয়ে ৩০ মিনিটে ৩৬ অ্যাম্বুলেন্স ঢাকা মেডিক্যাল হাসপাতালে', 'https://thedailycampus.com/student-movement-politics/147962/%E0%A6%97%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%AC%E0%A6%BF%E0%A6%A6%E0%A7%8D%E0%A6%A7-%E0%A6%86%E0%A6%B9%E0%A6%A4%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0', 'ঢাকা মেডিকেল কলেজ হাসপাতালে গুলিবিদ্ধ, আহতদের নিয়ে ৩০ মিনিটে সর্বমোট ৩৬টি অ্যাম্বুলেন্স প্রবেশ করে। বৃহস্পতিবার (১৮ জুলাই) সন্ধ্যার দিকে হাসপাতালে এ চিত্র দেখা যায়। অ্যাম্বুলেন্সগুলোয় নিয়ে আসা আহতদের বেশিরভাগ গুলিবিদ্ধ। এ পর্যন্ত হাসপাতালটিতে সর্বমোট ১৩০ জন হতাহত রোগী এসেছেন। সংবাদ জানিয়েছে দ্য বিজনেস স্ট্যান্ডার্ড।', 'https://web.archive.org/web/0/https://thedailycampus.com/student-movement-politics/147962/%E0%A6%97%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%AC%E0%A6%BF%E0%A6%A6%E0%A7%8D%E0%A6%A7-%E0%A6%86%E0%A6%B9%E0%A6%A4%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0', 'https://i.ibb.co/DkTjrQj/147962-149.jpg', 0, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (63, 'যাত্রাবাড়ীতে সংঘর্ষে ইউআইইউ শিক্ষার্থীর মৃত্যু', 'https://thedailycampus.com/private-university/147961/%E0%A6%AF%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%BE%E0%A6%AC%E0%A6%BE%E0%A7%9C%E0%A7%80%E0%A6%A4%E0%A7%87-%E0%A6%B8%E0%A6%82%E0%A6%98%E0%A6%B0%E0%A7%8D%E0%A6%B7%E0%A7%87-%E0%A6%87%E0%A6%89%E0%A6%86%E0%A6%87%E0%A6%87%E0%A6%89-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%B0-%E0%A6%AE%E0%A7%83%E0%A6%A4%E0%A7%8D%E0%A6%AF%E0%A7%81#:~:text=%E0%A6%B0%E0%A6%BE%E0%A6%9C%E0%A6%A7%E0%A6%BE%E0%A6%A8%E0%A7%80%E0%A6%B0%20%E0%A6%AF%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%BE%E0%A6%AC%E0%A6%BE%E0%A6%A1%E0%A6%BC%E0%A7%80%E0%A6%A4%E0%A7%87%20%E0%A6%AA%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%B6%E0%A7%87%E0%A6%B0%20%E0%A6%B8%E0%A6%99%E0%A7%8D%E0%A6%97%E0%A7%87%20%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE,%E0%A6%AC%E0%A6%BF%E0%A6%AD%E0%A6%BE%E0%A6%97%E0%A7%87%E0%A6%B0%20%E0%A6%A6%E0%A7%8D%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%80%E0%A6%AF%E0%A6%BC%20%E0%A6%AC%E0%A6%B0%E0%A7%8D%E0%A6%B7%E0%A7%87%E0%A6%B0%20%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%20%E0%A6%9B%E0%A6%BF%E0%A6%B2%E0%A7%87%E0%A6%A8%E0%A5%A4', 'রাজধানীর যাত্রাবাড়ীতে পুলিশের সঙ্গে কোটা সংস্কার আন্দোলনকারীদের সংঘর্ষে ইউনাইটেড ইন্টারন্যাশনাল ইউনিভার্সিটির (ইউআইইউ) এক শিক্ষার্থীর মৃত্যু হয়েছে। নিহত ওই শিক্ষার্থীর নাম মো. ইরফান ভূইয়া। তিনি বিশ্ববিদ্যালয়টির কম্পিউটার সাইন্স এন্ড ইঞ্জিনিয়ারিং বিভাগের দ্বিতীয় বর্ষের শিক্ষার্থী ছিলেন।', 'https://web.archive.org/web/0/https://thedailycampus.com/private-university/147961/%E0%A6%AF%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%BE%E0%A6%AC%E0%A6%BE%E0%A7%9C%E0%A7%80%E0%A6%A4%E0%A7%87-%E0%A6%B8%E0%A6%82%E0%A6%98%E0%A6%B0%E0%A7%8D%E0%A6%B7%E0%A7%87-%E0%A6%87%E0%A6%89%E0%A6%86%E0%A6%87%E0%A6%87%E0%A6%89-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%B0-%E0%A6%AE%E0%A7%83%E0%A6%A4%E0%A7%8D%E0%A6%AF%E0%A7%81#:~:text=%E0%A6%B0%E0%A6%BE%E0%A6%9C%E0%A6%A7%E0%A6%BE%E0%A6%A8%E0%A7%80%E0%A6%B0%20%E0%A6%AF%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%BE%E0%A6%AC%E0%A6%BE%E0%A6%A1%E0%A6%BC%E0%A7%80%E0%A6%A4%E0%A7%87%20%E0%A6%AA%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%B6%E0%A7%87%E0%A6%B0%20%E0%A6%B8%E0%A6%99%E0%A7%8D%E0%A6%97%E0%A7%87%20%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE,%E0%A6%AC%E0%A6%BF%E0%A6%AD%E0%A6%BE%E0%A6%97%E0%A7%87%E0%A6%B0%20%E0%A6%A6%E0%A7%8D%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%80%E0%A6%AF%E0%A6%BC%20%E0%A6%AC%E0%A6%B0%E0%A7%8D%E0%A6%B7%E0%A7%87%E0%A6%B0%20%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%20%E0%A6%9B%E0%A6%BF%E0%A6%B2%E0%A7%87%E0%A6%A8%E0%A5%A4', 'https://i.ibb.co/GWRLRws/147961-121.jpg', 1, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (64, '‘সরকার কি জিল্লুরকে ফিরিয়ে দিতে পারবে?’—জিজ্ঞাসা সহপাঠীদের', 'https://thedailycampus.com/student-movement-politics/147944/%E0%A6%B8%E0%A6%B0%E0%A6%95%E0%A6%BE%E0%A6%B0-%E0%A6%95%E0%A6%BF-%E0%A6%9C%E0%A6%BF%E0%A6%B2%E0%A7%8D%E0%A6%B2%E0%A7%81%E0%A6%B0%E0%A6%95%E0%A7%87-%E0%A6%AB%E0%A6%BF%E0%A6%B0%E0%A6%BF%E0%A7%9F%E0%A7%87-%E0%A6%A6%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%AA%E0%A6%BE%E0%A6%B0%E0%A6%AC%E0%A7%87?%E2%80%94%E0%A6%9C%E0%A6%BF%E0%A6%9C%E0%A7%8D%E0%A6%9E%E0%A6%BE%E0%A6%B8%E0%A6%BE-%E0%A6%B8%E0%A6%B9%E0%A6%AA%E0%A6%BE%E0%A6%A0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0', 'রাজধানীর আফতাবনগরে কোটা সংস্কারের দাবিতে আন্দোলনকারী শিক্ষার্থীদের সঙ্গে পুলিশের সংঘর্ষের সময় গুলিতে এক কলেজছাত্র নিহত হয়েছেন। বৃহস্পতিবার (১৮ জুলাই) দুপুর ২ টার দিকে এ ঘটনা ঘটে।', 'https://web.archive.org/web/0/https://thedailycampus.com/student-movement-politics/147944/%E0%A6%B8%E0%A6%B0%E0%A6%95%E0%A6%BE%E0%A6%B0-%E0%A6%95%E0%A6%BF-%E0%A6%9C%E0%A6%BF%E0%A6%B2%E0%A7%8D%E0%A6%B2%E0%A7%81%E0%A6%B0%E0%A6%95%E0%A7%87-%E0%A6%AB%E0%A6%BF%E0%A6%B0%E0%A6%BF%E0%A7%9F%E0%A7%87-%E0%A6%A6%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%AA%E0%A6%BE%E0%A6%B0%E0%A6%AC%E0%A7%87?%E2%80%94%E0%A6%9C%E0%A6%BF%E0%A6%9C%E0%A7%8D%E0%A6%9E%E0%A6%BE%E0%A6%B8%E0%A6%BE-%E0%A6%B8%E0%A6%B9%E0%A6%AA%E0%A6%BE%E0%A6%A0%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0', 'https://i.ibb.co/WkK6pTQ/147944-171.jpg', 1, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (65, 'কোটা সংস্কার আন্দোলনে সোহরাওয়ার্দী কলেজ শিক্ষার্থী গুলিবিদ্ধ', 'https://thedailycampus.com/public-university/147938/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%B8%E0%A6%82%E0%A6%B8%E0%A7%8D%E0%A6%95%E0%A6%BE%E0%A6%B0-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%B8%E0%A7%8B%E0%A6%B9%E0%A6%B0%E0%A6%BE%E0%A6%93%E0%A7%9F%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A6%E0%A7%80-%E0%A6%95%E0%A6%B2%E0%A7%87%E0%A6%9C-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80-%E0%A6%97%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%AC%E0%A6%BF%E0%A6%A6%E0%A7%8D%E0%A6%A7-', 'চলমান কোটা সংস্কার আন্দোলনে গুলিবিদ্ধ হয়েছেন সোহরাওয়ার্দী কলেজের শিক্ষার্থী জুলহাস জয়। তিনি ইংরেজি বিভাগের ২০১৮-১৯ শিক্ষাবর্ষের শিক্ষার্থী। বৃহস্পতিবার (১৮ জুলাই) দুপুরে গুলিবিদ্ধ হন জয়। রামপুরা এলাকায় বন্ধুদের সাথে কোটা সংস্কারের আন্দোলন করছিলেন।', 'https://web.archive.org/web/0/https://thedailycampus.com/public-university/147938/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%B8%E0%A6%82%E0%A6%B8%E0%A7%8D%E0%A6%95%E0%A6%BE%E0%A6%B0-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%B8%E0%A7%8B%E0%A6%B9%E0%A6%B0%E0%A6%BE%E0%A6%93%E0%A7%9F%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A6%E0%A7%80-%E0%A6%95%E0%A6%B2%E0%A7%87%E0%A6%9C-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80-%E0%A6%97%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%AC%E0%A6%BF%E0%A6%A6%E0%A7%8D%E0%A6%A7-', 'https://i.ibb.co/9WL0gF2/147938-177.jpg', 0, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (66, 'মার্কিন পররাষ্ট্র দপ্তরের প্রেস ব্রিফিংয়ে আলোচনায় ছাত্রলীগ', 'https://thedailycampus.com/other-world/147934/%E0%A6%AE%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%95%E0%A6%BF%E0%A6%A8-%E0%A6%AA%E0%A6%B0%E0%A6%B0%E0%A6%BE%E0%A6%B7%E0%A7%8D%E0%A6%9F%E0%A7%8D%E0%A6%B0-%E0%A6%A6%E0%A6%AA%E0%A7%8D%E0%A6%A4%E0%A6%B0%E0%A7%87%E0%A6%B0-%E0%A6%AA%E0%A7%8D%E0%A6%B0%E0%A7%87%E0%A6%B8-%E0%A6%AC%E0%A7%8D%E0%A6%B0%E0%A6%BF%E0%A6%AB%E0%A6%BF%E0%A6%82%E0%A7%9F%E0%A7%87-%E0%A6%86%E0%A6%B2%E0%A7%8B%E0%A6%9A%E0%A6%A8%E0%A6%BE%E0%A7%9F-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97', 'এবার যুক্তরাষ্ট্রের পররাষ্ট্র দপ্তরের ব্রিফিংয়ে বাংলাদেশি শিক্ষার্থীদের কোটা সংস্কার আন্দোলনের বিষয়টি উঠেছে। বুধবার (১৮ জুলাই) মার্কিন পররাষ্ট্র দপ্তরের নিয়মিত ওই ব্রিফিংয়ে সাংবাদিকদের প্রশ্নের জবাব দেন এ দপ্তরের মুখপাত্র ম্যাথু মিলার। যেখানে শিক্ষার্থীদের ওপর ক্ষমতাসীন দল আওয়ামী লীগের ভ্রাতৃপ্রতিম সংগঠন ছাত্রলীগের হামলার বিষয়টিও উঠে আসে।', 'https://web.archive.org/web/0/https://thedailycampus.com/other-world/147934/%E0%A6%AE%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%95%E0%A6%BF%E0%A6%A8-%E0%A6%AA%E0%A6%B0%E0%A6%B0%E0%A6%BE%E0%A6%B7%E0%A7%8D%E0%A6%9F%E0%A7%8D%E0%A6%B0-%E0%A6%A6%E0%A6%AA%E0%A7%8D%E0%A6%A4%E0%A6%B0%E0%A7%87%E0%A6%B0-%E0%A6%AA%E0%A7%8D%E0%A6%B0%E0%A7%87%E0%A6%B8-%E0%A6%AC%E0%A7%8D%E0%A6%B0%E0%A6%BF%E0%A6%AB%E0%A6%BF%E0%A6%82%E0%A7%9F%E0%A7%87-%E0%A6%86%E0%A6%B2%E0%A7%8B%E0%A6%9A%E0%A6%A8%E0%A6%BE%E0%A7%9F-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97', 'https://i.ibb.co/mcdLRPb/147934-129.jpg', 0, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (67, 'কুমিল্লায় পুলিশের সঙ্গে সংঘর্ষে আহত ১৩ শিক্ষার্থী', 'https://thedailycampus.com/student-movement-politics/147932/%E0%A6%95%E0%A7%81%E0%A6%AE%E0%A6%BF%E0%A6%B2%E0%A7%8D%E0%A6%B2%E0%A6%BE%E0%A7%9F-%E0%A6%AA%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%B6%E0%A7%87%E0%A6%B0-%E0%A6%B8%E0%A6%99%E0%A7%8D%E0%A6%97%E0%A7%87-%E0%A6%B8%E0%A6%82%E0%A6%98%E0%A6%B0%E0%A7%8D%E0%A6%B7%E0%A7%87-%E0%A6%86%E0%A6%B9%E0%A6%A4-%E0%A7%A7%E0%A7%A9-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80', 'চলমান কোটা সংস্কার আন্দোলনে শিক্ষার্থীদের চলা আন্দোলনে ‘কমপ্লিট শাটডাউনের’ প্রথম দিন কুমিল্লা সদর দক্ষিণ উপজেলার কোটবাড়ি বিশ্বরোডে পুলিশ, বিজিবি ও র‌্যাবের সঙ্গে আন্দোলনকারী শিক্ষার্থীদের ঘণ্টাব্যাপী পাল্টাপাল্টি ধাওয়া হয়।', 'https://web.archive.org/web/0/https://thedailycampus.com/student-movement-politics/147932/%E0%A6%95%E0%A7%81%E0%A6%AE%E0%A6%BF%E0%A6%B2%E0%A7%8D%E0%A6%B2%E0%A6%BE%E0%A7%9F-%E0%A6%AA%E0%A7%81%E0%A6%B2%E0%A6%BF%E0%A6%B6%E0%A7%87%E0%', 'https://i.ibb.co/RYwRRPH/147932-148.jpg', 0, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (68, 'কোটা আন্দোলনে গিয়ে গুলিবিদ্ধ আইইউবিএটির ৪ শিক্ষার্থী', 'https://thedailycampus.com/private-university/147929/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%97%E0%A6%BF%E0%A7%9F%E0%A7%87-', 'চলমান কোটা সংস্কার আন্দোলনে শিক্ষার্থীদের চলা আন্দোলনে রাজধানীর উত্তরা বিএনএস ও আজমপুরে পুলিশের সাথে সংঘর্ষের ঘটনায় ইন্টারন্যাশনাল ইউনিভার্সিটি অব বিজনেস এন্ড এগ্রিকালচার টেকনোলজির (আইইউবিএটি) গুলিবিদ্ধ হয়েছেন ৪ জন শিক্ষার্থী।', 'https://web.archive.org/web/0/https://thedailycampus.com/private-university/147929/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%97%E0%A6%BF%E0%A7%9F%E0%A7%87-', 'https://i.ibb.co/4KRnJvz/147929-111.jpg', 0, 1, '2024-07-18');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (69, 'চবিতে কোটাবিরোধী শিক্ষার্থীদের বেধড়ক পেটাল ছাত্রলীগ', 'https://www.ittefaq.com.bd/693808/%E0%A6%9A%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0%E0%A7%8B%E0%A6%A7%E0%A7%80-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%AC%E0%A7%87%E0%A6%A7%E0%A7%9C%E0%A6%95-%E0%A6%AA%E0%A7%87%E0%A6%9F%E0%A6%BE%E0%A6%B2', 'চট্টগ্রাম বিশ্ববিদ্যালয়ে (চবি) কোটাবিরোধী শিক্ষার্থীদের উপর ফের কয়েক দফায় হামলার অভিযোগ উঠেছে ছাত্রলীগের নেতাকর্মীদের বিরুদ্ধে। এ ঘটনায় দুই শিক্ষার্থী গুরুতর আহত হয়েছেন। সোমবার (১৫ই জুলাই) দুপুর আড়াইটার দিকে এ ঘটনা ঘটে।', 'https://web.archive.org/web/0/https://www.ittefaq.com.bd/693808/%E0%A6%9A%E0%A6%AC%E0%A6%BF%E0%A6%A4%E0%A7%87-%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE%E0%A6%AC%E0%A6%BF%E0%A6%B0%E0%A7%8B%E0%A6%A7%E0%A7%80-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%A6%E0%A7%87%E0%A6%B0-%E0%A6%AC%E0%A7%87%E0%A6%A7%E0%A7%9C%E0%A6%95-%E0%A6%AA%E0%A7%87%E0%A6%9F%E0%A6%BE%E0%A6%B2', 'https://i.ibb.co/1dPRB8v/6548468dbd9e606dfc5620fb67210576-6695569cb180b.webp', 0, 1, '2024-07-15');
INSERT OR REPLACE INTO news (id, title, link, description, archive_link, image, is_killed, approved, published) VALUES (70, 'কোটা আন্দোলনে যাওয়ায় ইবি শিক্ষার্থীকে ছাত্রলীগ নেতার মারধরের অভিযোগ', 'https://www.ittefaq.com.bd/693797/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%AF%E0%A6%BE%E0%A6%93%E0%A7%9F%E0%A6%BE%E0%A7%9F-%E0%A6%87%E0%A6%AC%E0%A6%BF-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%95%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97', 'সরকারি চাকরিতে কোটা-পদ্ধতি সংস্কারের দাবিতে দেশব্যাপী চলমান কোটা আন্দোলনে যাওয়ায় এক আবাসিক শিক্ষার্থীকে মারধর ও হল থেকে চলে যাওয়ার হুমকি দেওয়ার অভিযোগ উঠেছে ইসলামী বিশ্ববিদ্যালয় শাখা ছাত্রলীগের যুগ্ম সাধারণ সম্পাদক মেহেদী হাসান হাফিজের বিরুদ্ধে।', 'https://web.archive.org/web/0/https://www.ittefaq.com.bd/693797/%E0%A6%95%E0%A7%8B%E0%A6%9F%E0%A6%BE-%E0%A6%86%E0%A6%A8%E0%A7%8D%E0%A6%A6%E0%A7%8B%E0%A6%B2%E0%A6%A8%E0%A7%87-%E0%A6%AF%E0%A6%BE%E0%A6%93%E0%A7%9F%E0%A6%BE%E0%A7%9F-%E0%A6%87%E0%A6%AC%E0%A6%BF-%E0%A6%B6%E0%A6%BF%E0%A6%95%E0%A7%8D%E0%A6%B7%E0%A6%BE%E0%A6%B0%E0%A7%8D%E0%A6%A5%E0%A7%80%E0%A6%95%E0%A7%87-%E0%A6%9B%E0%A6%BE%E0%A6%A4%E0%A7%8D%E0%A6%B0%E0%A6%B2%E0%A7%80%E0%A6%97', 'https://i.ibb.co/kQq7LPt/ced10b0d2f655ab6d687d5d0af88d280-6695220d648d2.webp', 0, 1, '2024-07-15');
